-- ============================================================================
--  MisfatDB — jeu de données de démonstration
--  Projet : Bilan Carbone Groupe MISFAT
-- ============================================================================
--
--  OBJET
--  Rendre une base MisfatDB vide immédiatement exploitable : référentiel
--  carbone complet, structure du groupe, exercices, taux de change et quelques
--  mesures d'exemple. C'est ce jeu que les écrans de saisie, le tableau de bord
--  et le rapport Bilan Carbone attendent pour afficher autre chose que des
--  colonnes vides.
--
--  PRÉ-REQUIS
--  Le schéma doit déjà exister. Il est créé par Hibernate au premier démarrage
--  des microservices (ddl-auto=update) : lancez emission-service et
--  organization-service une première fois, puis exécutez ce script.
--
--  EXÉCUTION
--    sqlcmd -S localhost -d MisfatDB -E -C -i db_initial.sql
--  ou, depuis SQL Server Management Studio, ouvrir le fichier et exécuter.
--
--  IDEMPOTENCE
--  Le script vide les tables concernées avant de les réalimenter : il peut être
--  rejoué autant de fois que nécessaire et laisse toujours la base dans le même
--  état. Il ne touche à aucune autre table.
--
--  DONNÉES PERSONNELLES
--  Les comptes réels ne sont pas repris. Quatre comptes de démonstration sont
--  créés à la place, un par profil d'accès, sans mot de passe : l'annuaire
--  n'authentifie personne, les identifiants appartiennent au fournisseur
--  d'identité externe.
--
--  CONTENU
--    ref_scopes                  3     les trois scopes du GHG Protocol
--    ref_categories             19     catégories rattachées aux scopes
--    ref_carbon_references     114     références carbone MISFAT (MS…)
--    ref_emission_sources       96     sources d'émission documentées
--    emission_factor           140     facteurs, physiques et monétaires
--    filiale                     5     entités du groupe
--    usine                       8     sites de production
--    annee_reference             5     exercices ouverts
--    import_source_type          6     gabarits d'import Excel
--    currency_exchange_rate   1906     taux de change par devise et période
--    emission_measure            3     mesures d'exemple
--    utilisateurs                4     comptes de démonstration
--
-- ============================================================================

SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

USE MisfatDB;
GO

PRINT '--- Purge des tables de référence ---';
GO

-- L'ordre suit les dépendances à l'envers : ce qui référence disparaît avant ce
-- qui est référencé.
IF OBJECT_ID('dbo.emission_measure', 'U') IS NOT NULL DELETE FROM dbo.emission_measure;
IF OBJECT_ID('dbo.gas_emission_detail', 'U') IS NOT NULL DELETE FROM dbo.gas_emission_detail;
IF OBJECT_ID('dbo.import_log', 'U') IS NOT NULL DELETE FROM dbo.import_log;
IF OBJECT_ID('dbo.emission_factor', 'U') IS NOT NULL DELETE FROM dbo.emission_factor;
IF OBJECT_ID('dbo.ref_carbon_references', 'U') IS NOT NULL DELETE FROM dbo.ref_carbon_references;
IF OBJECT_ID('dbo.ref_categories', 'U') IS NOT NULL DELETE FROM dbo.ref_categories;
IF OBJECT_ID('dbo.ref_scopes', 'U') IS NOT NULL DELETE FROM dbo.ref_scopes;
IF OBJECT_ID('dbo.ref_emission_sources', 'U') IS NOT NULL DELETE FROM dbo.ref_emission_sources;
IF OBJECT_ID('dbo.currency_exchange_rate', 'U') IS NOT NULL DELETE FROM dbo.currency_exchange_rate;
IF OBJECT_ID('dbo.import_source_type', 'U') IS NOT NULL DELETE FROM dbo.import_source_type;
IF OBJECT_ID('dbo.annee_reference', 'U') IS NOT NULL DELETE FROM dbo.annee_reference;
IF OBJECT_ID('dbo.usine', 'U') IS NOT NULL DELETE FROM dbo.usine;
IF OBJECT_ID('dbo.filiale', 'U') IS NOT NULL DELETE FROM dbo.filiale;
GO

PRINT '--- Insertion du jeu de démonstration ---';
GO

-- ---------------------------------------------------------------------------
-- ref_scopes — 3 ligne(s)
-- ---------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.ref_scopes ON;
SET IDENTITY_INSERT dbo.ref_scopes OFF;
GO

-- ---------------------------------------------------------------------------
-- ref_categories — 19 ligne(s)
-- ---------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.ref_categories ON;
SET IDENTITY_INSERT dbo.ref_categories OFF;
GO

-- ---------------------------------------------------------------------------
-- ref_carbon_references — 114 ligne(s)
-- ---------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.ref_carbon_references ON;
SET IDENTITY_INSERT dbo.ref_carbon_references OFF;
GO

-- ---------------------------------------------------------------------------
-- ref_emission_sources — 96 ligne(s)
-- ---------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.ref_emission_sources ON;
SET IDENTITY_INSERT dbo.ref_emission_sources OFF;
GO

-- ---------------------------------------------------------------------------
-- emission_factor — 140 ligne(s)
-- ---------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.emission_factor ON;
SET IDENTITY_INSERT dbo.emission_factor OFF;
GO

-- ---------------------------------------------------------------------------
-- filiale — 5 ligne(s)
-- ---------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.filiale ON;
SET IDENTITY_INSERT dbo.filiale OFF;
GO

-- ---------------------------------------------------------------------------
-- usine — 8 ligne(s)
-- ---------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.usine ON;
SET IDENTITY_INSERT dbo.usine OFF;
GO

-- ---------------------------------------------------------------------------
-- annee_reference — 5 ligne(s)
-- ---------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.annee_reference ON;
SET IDENTITY_INSERT dbo.annee_reference OFF;
GO

-- ---------------------------------------------------------------------------
-- import_source_type — 6 ligne(s)
-- ---------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.import_source_type ON;
SET IDENTITY_INSERT dbo.import_source_type OFF;
GO

-- ---------------------------------------------------------------------------
-- currency_exchange_rate — 1906 ligne(s)
-- ---------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.currency_exchange_rate ON;
SET IDENTITY_INSERT dbo.currency_exchange_rate OFF;
GO

-- ---------------------------------------------------------------------------
-- emission_measure — 3 ligne(s)
-- ---------------------------------------------------------------------------
SET IDENTITY_INSERT dbo.emission_measure ON;
SET IDENTITY_INSERT dbo.emission_measure OFF;
GO

-- ---------------------------------------------------------------------------
-- utilisateurs — 4 comptes de démonstration, un par profil d'accès
-- ---------------------------------------------------------------------------
--
-- Le rôle déposé à la connexion commande la navigation :
--   ADMINISTRATEUR → Master Admin      accès total, paramétrage, rapport complet
--   CONTRIBUTEUR   → Responsable/Saisie écrans Scope 1/2/3, imports Excel
--   AUDITEUR       → Validateur         tableau de bord et rapports, sans saisie
--   USER           → lecture seule      repli le plus restreint
--
-- Le mot de passe reste vide : l'authentification appartient à Keycloak. Ces
-- lignes servent à peupler l'annuaire et à exercer les rôles, pas à ouvrir une
-- session sans contrôle.
DELETE FROM dbo.utilisateurs;
GO
SET IDENTITY_INSERT dbo.utilisateurs ON;
SET IDENTITY_INSERT dbo.utilisateurs OFF;
GO

-- ============================================================================
--  Contrôle du chargement
-- ============================================================================
PRINT '--- Contrôle ---';
GO

SELECT 'ref_scopes' AS table_chargee, COUNT(*) AS lignes FROM dbo.ref_scopes
UNION ALL SELECT 'ref_categories', COUNT(*) FROM dbo.ref_categories
UNION ALL SELECT 'ref_carbon_references', COUNT(*) FROM dbo.ref_carbon_references
UNION ALL SELECT 'ref_emission_sources', COUNT(*) FROM dbo.ref_emission_sources
UNION ALL SELECT 'emission_factor', COUNT(*) FROM dbo.emission_factor
UNION ALL SELECT 'filiale', COUNT(*) FROM dbo.filiale
UNION ALL SELECT 'usine', COUNT(*) FROM dbo.usine
UNION ALL SELECT 'annee_reference', COUNT(*) FROM dbo.annee_reference
UNION ALL SELECT 'import_source_type', COUNT(*) FROM dbo.import_source_type
UNION ALL SELECT 'currency_exchange_rate', COUNT(*) FROM dbo.currency_exchange_rate
UNION ALL SELECT 'emission_measure', COUNT(*) FROM dbo.emission_measure
UNION ALL SELECT 'utilisateurs', COUNT(*) FROM dbo.utilisateurs
ORDER BY table_chargee;
GO

-- Les unités doivent être canoniques : « kWh », « kg », « km », jamais « KWH ».
-- Un import Excel ultérieur les normalise à l'écriture ; ce contrôle vérifie que
-- le jeu chargé l'est déjà.
SELECT DISTINCT unit AS unite_facteur FROM dbo.emission_factor WHERE unit IS NOT NULL ORDER BY unit;
GO

PRINT 'Jeu de démonstration chargé.';
GO
